/* eslint-disable max-len */

'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var isAlmostEqual = require( '@stdlib/assert/is-almost-equal-float64array' );
var dorgl2 = require( './../lib/ndarray.js' );


// FIXTURES //

var ROW_MAJ = require( './fixtures/row_major.json' );
var COL_MAJ = require( './fixtures/column_major.json' );
var LAR_STR_ROW_MAJ = require( './fixtures/large_strides/row_major.json' );
var LAR_STR_COL_MAJ = require( './fixtures/large_strides/column_major.json' );
var MIX_STR_ROW_MAJ = require( './fixtures/mixed_strides/row_major.json' );
var MIX_STR_COL_MAJ = require( './fixtures/mixed_strides/column_major.json' );
var NEG_STR_ROW_MAJ = require( './fixtures/negative_strides/row_major.json' );
var NEG_STR_COL_MAJ = require( './fixtures/negative_strides/column_major.json' );
var OFF_ROW_MAJ = require( './fixtures/offsets/row_major.json' );
var OFF_COL_MAJ = require( './fixtures/offsets/column_major.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dorgl2, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 13', function test( t ) {
	t.strictEqual( dorgl2.length, 13, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided a first argument which is greater than `N`', function test( t ) {
	var values;
	var work;
	var TAU;
	var A;
	var i;

	A = new Float64Array( 12 );
	TAU = new Float64Array( 2 );
	work = new Float64Array( 3 );

	values = [
		5,
		6,
		7
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), RangeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dorgl2( value, 4, 2, A, 4, 1, 0, TAU, 1, 0, work, 1, 0 );
		};
	}
});

tape( 'the function throws an error if provided a third argument which is greater than `M`', function test( t ) {
	var values;
	var work;
	var TAU;
	var A;
	var i;

	A = new Float64Array( 12 );
	TAU = new Float64Array( 2 );
	work = new Float64Array( 3 );

	values = [
		4,
		5,
		6
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), RangeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dorgl2( 3, 4, value, A, 4, 1, 0, TAU, 1, 0, work, 1, 0 );
		};
	}
});

tape( 'the function generates an M-by-N real orthogonal matrix from the elementary reflector (row-major)', function test( t ) {
	var expectedWork;
	var expectedA;
	var info;
	var data;
	var work;
	var TAU;
	var A;

	data = ROW_MAJ;

	A = new Float64Array( data.A );
	TAU = new Float64Array( data.TAU );
	work = new Float64Array( 3 );

	expectedA = new Float64Array( data.A_out );
	expectedWork = new Float64Array( data.WORK_out );

	info = dorgl2( data.M, data.N, data.K, A, data.strideA1, data.strideA2, data.offsetA, TAU, data.strideTAU, data.offsetTAU, work, data.strideWORK, data.offsetWORK );
	t.strictEqual( info, 0, 'returns expected value' );
	t.strictEqual( isAlmostEqual( A, expectedA, 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostEqual( work, expectedWork, 1 ), true, 'returns expected value' );
	t.end();
});

